let monthSettingsGeneration=0
const form=reactive({store_name:'',period:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()),scheduled_days:26})
const rosterVisible=ref(false),rosterPreview=ref({rows:[],version:0}),attendanceLoading=ref(false),attendanceError=ref('')
let savedItemsSignature='',attendanceGeneration=0
const itemsSignature=items=>JSON.stringify((items || []).map(({attendance_preview,...row})=>row))
const attendanceOf=row=>row.attendance_preview || row.attendance_snapshot
const attendanceNumber=(row,key)=>{const source=attendanceOf(row);return !source?.available?'—':source[key]===null?'待核':source[key] ?? '—'}
const context=ref({can_prepare:false,can_attendance:false,can_standard:false,own_only:false})
const monthSettings=reactive({group:{scheduled_days:26,version:0,published_at:null},store:{scheduled_days:26,version:0,published_at:null}})
const affiliation=computed({get:()=>stores.value.find(store=>store.store_name===form.store_name)?.id || form.store_name,set:value=>{form.store_name=stores.value.find(store=>Number(store.id)===Number(value))?.store_name || value || ''}})
const attendanceColumns=[{key:'personal_leave',label:'事假（天）'},{key:'sick_leave',label:'病假（天）'},{key:'join_leave',label:'入/离职缺勤'},{key:'dispatch_out_days',label:'派出天数'},{key:'support_days',label:'支援天数'},{key:'annual_leave',label:'年假'},{key:'weekday_overtime_hours',label:'工作日加班时长'},{key:'restday_overtime_hours',label:'休息日加班时长'}]
const salaryColumns=[{key:'base_salary',label:'基本工资'},{key:'position_allowance',label:'岗位补贴'},{key:'performance_salary',label:'绩效工资'},{key:'attendance_bonus',label:'全勤奖'},{key:'housing_allowance',label:'房补'}]
const monthlyColumns=[{key:'reward',label:'奖励'},{key:'penalty',label:'罚款'},{key:'late_early_deduction',label:'迟到早退'},{key:'other_deduction',label:'其他扣款'},{key:'social_insurance',label:'社保'},{key:'income_tax',label:'个税'},{key:'utilities_fee',label:'水电'},{key:'uniform_deposit',label:'工衣押金'}]
const adjustmentColumns=computed(()=>monthlyColumns.slice(0,4).filter(c=>!['penalty','late_early_deduction'].includes(c.key) || sheet.value?.items.some(r=>Number(r[c.key])>0)))
const deductionEditor=reactive({open:false,row:null,key:'',name:'',label:'',amount:'',note:''})
const canEditDeduction=(row,key)=>!row.supervisor_display_only && (['social_insurance','income_tax'].includes(key)?sheet.value?.can_edit_deductions:sheet.value?.can_edit || sheet.value?.can_edit_deductions)
function editDeduction(row,column){Object.assign(deductionEditor,{open:true,row,key:column.key,name:row.name,label:column.label,amount:String(row[column.key] || 0),note:row.deduction_notes?.[column.key] || ''})}
function applyDeduction(){const e=deductionEditor,value=Number(e.amount);if(!e.amount.trim() || !Number.isFinite(value) || value<0 || value>10000000){ElMessage.warning('请输入有效的非负金额');return}if(value>0 && !e.note.trim()){ElMessage.warning('请填写扣款原因');return}e.row[e.key]=value;e.row.deduction_notes={...e.row.deduction_notes,[e.key]:e.note.trim()};e.open=false}
const n=v=>Math.max(0,Number(v)||0)
const adjusted=(r,key,value)=>Object.hasOwn(r.salary_overrides || {},key)?n(r.salary_overrides[key]):value
const setOverride=(r,key,value)=>{r.salary_overrides={...(r.salary_overrides || {}),[key]:value}}
const actualDays=r=>adjusted(r,'actual_days',Math.max(0,n(r.scheduled_days)-n(r.personal_leave)-n(r.sick_leave)-n(r.join_leave)-n(r.dispatch_out_days)+n(r.support_days)+n(r.annual_leave)))
const standardSalary=r=>r.hire_type==='兼职'?n(r.part_time_hourly_rate):['base_salary','position_allowance','performance_salary','attendance_bonus','housing_allowance'].reduce((s,k)=>s+n(r[k]),0)
const actualComponent=(r,key)=>adjusted(r,'actual_'+key,r.hire_type==='兼职'?0:n(r[key])*actualDays(r)/Math.max(1,n(r.payroll_base_days)||n(r.scheduled_days)))
const weekdayOvertimePay=r=>adjusted(r,'weekday_overtime_pay',n(r.weekday_overtime_hours)*n(r.weekday_overtime_rate))
const restdayOvertimePay=r=>adjusted(r,'restday_overtime_pay',n(r.restday_overtime_hours)*n(r.restday_overtime_rate))
const partTimePay=r=>adjusted(r,'part_time_salary',n(r.part_time_hours)*n(r.part_time_hourly_rate))
const grossSalary=r=>['base_salary','position_allowance','performance_salary','attendance_bonus','housing_allowance'].reduce((s,k)=>s+actualComponent(r,k),0)+weekdayOvertimePay(r)+restdayOvertimePay(r)+partTimePay(r)+n(r.reward)-n(r.penalty)-n(r.late_early_deduction)-n(r.other_deduction)
const deductions=r=>['social_insurance','income_tax','utilities_fee','uniform_deposit'].reduce((s,k)=>s+n(r[k]),0)
const netSalary=r=>grossSalary(r)-deductions(r)
const summary=computed(()=> (sheet.value?.items||[]).reduce((o,r)=>({gross:o.gross+grossSalary(r),deductions:o.deductions+deductions(r),net:o.net+netSalary(r)}),{gross:0,deductions:0,net:0}))
async function loadLists(){
  if(props.detailOnly)return;
  listsLoading.value=true;listError.value='';
  try{const[a,b]=await Promise.all([getPayrollContext(),getPayrollSheets('work')]);context.value=a.context;stores.value=a.context.stores;savedSheets.value=b.sheets||[];if(context.value.own_only)form.store_name=stores.value[0]?.store_name || ''}
  catch(e){listError.value='工资表资料读取失败：'+e.message;ElMessage.error(listError.value)}
  finally{listsLoading.value=false}
}
async function prepareSheet(){if(!form.store_name||!form.period){ElMessage.warning('请选择员工归属和工资月份');return}preparing.value=true;try{sheet.value=(await preparePayrollSheet(form)).sheet;savedItemsSignature=itemsSignature(sheet.value.items);await loadAttendancePreview();await loadLists();ElMessage.success('工资表已打开')}catch(e){ElMessage.error('生成失败：'+e.message)}finally{preparing.value=false}}
async function loadMonthSetting(){
  if(!form.period)return;
  const request=++monthSettingsGeneration;monthSettingsLoading.value=true;monthSettingsError.value='';
  try{const result=await getPayrollMonthSetting(form.period);if(request===monthSettingsGeneration)Object.assign(monthSettings,result.settings)}
  catch(e){if(request===monthSettingsGeneration){monthSettingsError.value='本月出勤标准读取失败';ElMessage.error('读取本月应出勤设置失败：'+e.message)}}
  finally{if(request===monthSettingsGeneration)monthSettingsLoading.value=false}
}
async function loadSavedSheet(id){loadingSheet.value=true;loadError.value='';try{sheet.value=(await (props.detailOnly?getPayrollReviewSheet(props.reviewPeriod,id):getPayrollSheet(id))).sheet;Object.assign(form,{store_name:sheet.value.store_name,period:sheet.value.period,scheduled_days:sheet.value.scheduled_days});if(!props.detailOnly)await loadMonthSetting();savedItemsSignature=itemsSignature(sheet.value.items);await loadAttendancePreview()}catch(e){loadError.value='打开失败：'+e.message;ElMessage.error(loadError.value)}finally{loadingSheet.value=false}}
async function loadAttendancePreview(){
  const current=sheet.value,request=++attendanceGeneration;attendanceError.value='';
  if(!current?.can_edit || props.detailOnly)return;
  attendanceLoading.value=true;
  try{const result=await previewRosterPayroll(current.id);if(request!==attendanceGeneration || sheet.value?.id!==current.id)return;rosterPreview.value=result;for(const row of current.items)row.attendance_preview=result.rows.find(item=>item.id===row.id)?.attendance}
  catch(error){if(request===attendanceGeneration)attendanceError.value='考勤读取失败：'+error.message}
  finally{if(request===attendanceGeneration)attendanceLoading.value=false}
}
async function previewRoster(){if(itemsSignature(sheet.value.items)!==savedItemsSignature){ElMessage.warning('请先保存工资明细，再更新考勤');return}await loadAttendancePreview();if(!attendanceError.value)rosterVisible.value=true}
async function applyRoster(mode){try{if(mode==='payroll')await ElMessageBox.confirm('带入已核实整月的计薪、事假和病假天数，重新计算实际工资；正式员工加班工资置零并按存假规则处理。确认继续？','带入计薪考勤');saving.value=true;const result=await applyRosterPayroll(sheet.value.id,{version:rosterPreview.value.version,source_token:rosterPreview.value.source_token,mode});rosterVisible.value=false;await loadSavedSheet(sheet.value.id);await loadLists();ElMessage.success(`已更新 ${result.applied_count} 位员工${mode==='attendance'?'的考勤汇总':'的计薪考勤'}`)}catch(error){if(error!=='cancel' && error!=='close')ElMessage.error(error.message)}finally{saving.value=false}}
async function persistSheet(){sheet.value=(await savePayrollSheet(sheet.value.id,{version:sheet.value.version,items:sheet.value.items})).sheet;savedItemsSignature=itemsSignature(sheet.value.items);await loadLists()}
async function persistDeductions(){sheet.value=(await savePayrollDeductions(sheet.value.id,{version:sheet.value.version,items:sheet.value.items.map(row=>Object.fromEntries(['id','employee_id','social_insurance','income_tax','utilities_fee','uniform_deposit','deduction_notes'].map(key=>[key,row[key]])))})).sheet}
async function saveDeductions(){saving.value=true;try{await persistDeductions();ElMessage.success('代扣代缴已保存')}catch(e){ElMessage.error('保存失败：'+e.message)}finally{saving.value=false}}
async function saveSheet(){if(!sheet.value)return;saving.value=true;try{await persistSheet();ElMessage.success('工资表明细已保存')}catch(e){ElMessage.error('保存失败：'+e.message)}finally{saving.value=false}}
async function submitSheet(){saving.value=true;try{await persistSheet();sheet.value=(await submitPayrollSheet(sheet.value.id,{version:sheet.value.version})).sheet;await loadLists();sheet.value=null;ElMessage.success('已提交至工资审核，已从待处理列表移除')}catch(e){ElMessage.error('提交失败：'+e.message)}finally{saving.value=false}}
async function reviewSheet(action){try{let note='';if(action==='return'){const result=await ElMessageBox.prompt('请说明需修改的内容','退回工资表',{inputValidator:value=>!!value?.trim() || '请填写退回原因'});note=result.value}else await ElMessageBox.confirm(action==='hr_approve'?'确认考勤与应发工资无误？通过后转交财务填写扣缴并审核。':'确认财务审核通过当前工资表？通过后将锁定。','工资审核');if(sheet.value.can_edit_deductions)await persistDeductions();sheet.value=(await reviewPayrollSheet(sheet.value.id,{version:sheet.value.version,action,note})).sheet;await loadLists();emit('changed');ElMessage.success(action==='return'?'已退回，等待门店重新提交':action==='hr_approve'?'人事核对完成，已转交财务':'财务审核通过')}catch(e){if(e!=='cancel' && e!=='close')ElMessage.error('审核失败：'+e.message)}}
async function downloadSheet(){try{const draft=sheet.value.status!=='已审核',blob=await exportPayrollSheet(sheet.value.id,draft),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`${sheet.value.store_name}-${sheet.value.period}${draft?'草稿-未审核':'已审核'}工资表.xlsx`;a.click();URL.revokeObjectURL(href)}catch(e){ElMessage.error('导出失败：'+e.message)}}
watch(()=>[props.sheetId,props.reviewPeriod],async()=>{if(props.detailOnly){sheet.value=null;if(props.sheetId)await loadSavedSheet(props.sheetId)}})
onMounted(async()=>{await loadLists();if(props.detailOnly){if(props.sheetId)await loadSavedSheet(props.sheetId)}else await loadMonthSetting()})
</script>

